"use client";
// @zeus-internal
import { RotateCcw } from "lucide-react";
import { useEffect, useState } from "react";
import { ArtemisButton } from "../../../foundations/button";
import { demoTime, INCOMING, INITIAL_ENTRIES, type LogEntry, STREAM_INTERVAL_MS } from "./01-execution/data";
import { LogExplorer } from "./01-execution/log-explorer";
import { ArtemisMorphicTooltip } from "./01-execution/morphic-tooltip";
export default function LogExplorerExecution() {
    const [entries, setEntries] = useState<LogEntry[]>(INITIAL_ENTRIES);
    const [paused, setPaused] = useState(false);
    const [version, setVersion] = useState(0);
    useEffect(() => {
        let next = 0;
        const timer = window.setInterval(() => {
            const index = next++;
            const entry: LogEntry = {
                ...INCOMING[index % INCOMING.length],
                id: `stream-${version}-${index}`,
                time: demoTime(index + 1),
            };
            setEntries((current) => [...current.slice(-79), entry]);
        }, STREAM_INTERVAL_MS);
        return () => window.clearInterval(timer);
    }, [version]);
    return (<>
      <LogExplorer entries={entries} service="event-pipeline" environment="staging" paused={paused} onPausedChange={setPaused} headerActions={<ArtemisMorphicTooltip content="Reset demo">
            <ArtemisButton tabIndex={0} variant="ghost" size="icon" aria-label="Reset demo" className="art:size-9 art:rounded-full art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring" onClick={() => {
                setEntries(INITIAL_ENTRIES);
                setPaused(false);
                setVersion((current) => current + 1);
            }}>
              <RotateCcw aria-hidden className="art:size-3.5"/>
            </ArtemisButton>
          </ArtemisMorphicTooltip>}/>
    </>);
}

