"use client";
// @zeus-internal
import { motion, type Transition, useReducedMotion } from "motion/react";
import { type KeyboardEvent, type ReactNode, useId, useRef } from "react";
import { artemisCx } from "../../../../lib/utils";
export type LevelTab<T extends string> = {
    value: T;
    label: ReactNode;
    id: string;
};
const BUTTON_BASE = "art:relative art:z-10 art:inline-flex art:items-center art:justify-center art:whitespace-nowrap art:bg-transparent art:font-medium art:outline-none art:transition-colors art:duration-150 art:motion-reduce:delay-0 art:motion-reduce:transition-none";
const BUTTON_ACTIVE = "art:text-foreground art:delay-100";
const BUTTON_IDLE = "art:text-muted-foreground art:delay-0 art:hover:text-foreground";
const BUTTON_SIZE = "art:rounded-full art:h-8 art:gap-1 art:px-2 art:py-0 art:text-xs art:@min-[640px]/artemis:gap-1.5 art:@min-[640px]/artemis:px-3 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background";
const INDICATOR_TRANSITION: Transition = { type: "spring", stiffness: 245, damping: 36, mass: 1.2 };
export function LevelTabs<T extends string>({ items, value, onValueChange, controls, ariaLabel, }: {
    items: readonly LevelTab<T>[];
    value: T;
    onValueChange: (value: T) => void;
    controls: string;
    ariaLabel: string;
}) {
    const layoutId = useId();
    const reduce = useReducedMotion();
    const refs = useRef<Array<HTMLButtonElement | null>>([]);
    const select = (index: number) => {
        const next = items[(index + items.length) % items.length];
        onValueChange(next.value);
        refs.current[(index + items.length) % items.length]?.focus();
    };
    const onKeyDown = (event: KeyboardEvent<HTMLButtonElement>, index: number) => {
        if (event.key === "ArrowRight")
            select(index + 1);
        else if (event.key === "ArrowLeft")
            select(index - 1);
        else if (event.key === "Home")
            select(0);
        else if (event.key === "End")
            select(items.length - 1);
        else
            return;
        event.preventDefault();
    };
    return (<div role="tablist" className="art:inline-flex art:items-center art:rounded-full art:bg-muted art:gap-0.5 art:p-0.5" aria-label={ariaLabel}>
      {items.map((item, index) => {
            const active = item.value === value;
            return (<div key={item.value} className="art:relative">
            {active ? (<motion.span layoutId={layoutId} className="art:absolute art:inset-0 art:bg-background art:rounded-full" style={{ borderRadius: 9999 }} transition={reduce ? { duration: 0 } : INDICATOR_TRANSITION}/>) : null}
            <button ref={(el) => {
                    refs.current[index] = el;
                }} type="button" role="tab" aria-selected={active} className={artemisCx(BUTTON_BASE, active ? BUTTON_ACTIVE : BUTTON_IDLE, BUTTON_SIZE)} id={item.id} aria-controls={controls} tabIndex={active ? 0 : -1} onClick={() => onValueChange(item.value)} onKeyDown={(event) => onKeyDown(event, index)}>
              {item.label}
            </button>
          </div>);
        })}
    </div>);
}

"use client";
// @zeus-internal
import { ArrowDown, Circle, Pause, Play, Search, X } from "lucide-react";
import { motion } from "motion/react";
import { type ReactNode, useEffect, useId, useLayoutEffect, useMemo, useRef, useState } from "react";
import { ArtemisButton } from "../../../../foundations/button";
import { ARTEMIS_EASE_OUT } from "../../../../lib/ease";
import { artemisCx } from "../../../../lib/utils";
import type { LogEntry, LogLevel } from "./data";
import { LevelTabs } from "./level-tabs";
import { LogRow } from "./log-row";
import { ArtemisMorphicTooltip } from "./morphic-tooltip";
import { CircleAlert, FOCUS_RING } from "./shared";
type LevelFilter = "all" | LogLevel;
const LEVELS: readonly {
    value: LevelFilter;
    label: string;
}[] = [
    { value: "all", label: "All" },
    { value: "info", label: "Info" },
    { value: "warn", label: "Warn" },
    { value: "error", label: "Error" },
];
const FOLLOW_THRESHOLD = 24;
function matches(entry: LogEntry, query: string): boolean {
    if (!query)
        return true;
    return `${entry.time} ${entry.level} ${entry.message} ${entry.context}`.toLowerCase().includes(query);
}
export function LogExplorer({ entries, service, environment, paused, onPausedChange, headerActions, }: {
    entries: LogEntry[];
    service: string;
    environment: string;
    paused: boolean;
    onPausedChange: (paused: boolean) => void;
    headerActions?: ReactNode;
}) {
    const id = useId();
    const searchId = useId();
    const listRef = useRef<HTMLDivElement>(null);
    const searchRef = useRef<HTMLInputElement>(null);
    const [level, setLevel] = useState<LevelFilter>("all");
    const [query, setQuery] = useState("");
    const [searchFocused, setSearchFocused] = useState(false);
    const [expandedId, setExpandedId] = useState<string | null>(null);
    const [following, setFollowing] = useState(true);
    const [scrolled, setScrolled] = useState(false);
    const [snapshot, setSnapshot] = useState<LogEntry[] | null>(null);
    useEffect(() => {
        setSnapshot((current) => (paused ? (current ?? entries) : null));
    }, [paused]);
    const shown = paused && snapshot ? snapshot : entries;
    const pending = paused && snapshot ? entries.filter((entry) => !snapshot.includes(entry)).length : 0;
    const needle = query.trim().toLowerCase();
    const counts = useMemo(() => ({
        all: shown.length,
        info: shown.filter((entry) => entry.level === "info").length,
        warn: shown.filter((entry) => entry.level === "warn").length,
        error: shown.filter((entry) => entry.level === "error").length,
    }) satisfies Record<LevelFilter, number>, [shown]);
    const visible = useMemo(() => shown.filter((entry) => (level === "all" || entry.level === level) && matches(entry, needle)), [shown, level, needle]);
    useLayoutEffect(() => {
        const el = listRef.current;
        if (!el || !following)
            return;
        el.scrollTop = el.scrollHeight;
    }, [visible, following]);
    const onScroll = () => {
        const el = listRef.current;
        if (!el)
            return;
        setScrolled(el.scrollTop > 0);
        setFollowing(el.scrollHeight - el.scrollTop - el.clientHeight <= FOLLOW_THRESHOLD);
    };
    const jumpToLatest = () => {
        setExpandedId(null);
        setFollowing(true);
        const el = listRef.current;
        if (el)
            el.scrollTop = el.scrollHeight;
    };
    const changeLevel = (next: LevelFilter) => {
        if (next === level)
            return;
        setLevel(next);
        setExpandedId(null);
        setFollowing(true);
    };
    const changeQuery = (next: string) => {
        setQuery(next);
        setExpandedId(null);
    };
    const clearFilters = () => {
        changeLevel("all");
        changeQuery("");
        searchRef.current?.focus();
    };
    const tabs = LEVELS.map((item) => ({
        value: item.value,
        id: `${id}-${item.value}`,
        label: (<>
        {item.label}
        <span className="art:font-mono art:text-xs art:tabular-nums art:text-muted-foreground">{counts[item.value]}</span>
      </>),
    }));
    return (<section aria-labelledby={`${id}-title`} className="art:flex art:h-144 art:w-full art:max-w-5xl art:flex-col art:overflow-hidden art:rounded-3xl art:bg-muted art:text-foreground">
      <header className="art:grid art:shrink-0 art:grid-cols-[minmax(0,1fr)_auto] art:items-center art:gap-3 art:px-4 art:py-4 art:@min-[640px]/artemis:grid-cols-[auto_minmax(0,1fr)_auto] art:@min-[640px]/artemis:px-6">
        <h2 id={`${id}-title`} className="art:text-xl art:font-medium">
          Execution logs
        </h2>
        <span className="art:col-span-2 art:col-start-1 art:row-start-2 art:max-w-full art:justify-self-start art:truncate art:rounded-full art:border art:border-border art:px-2.5 art:py-1 art:font-mono art:text-xs art:text-muted-foreground art:@min-[640px]/artemis:col-span-1 art:@min-[640px]/artemis:col-start-2 art:@min-[640px]/artemis:row-start-1">
          {`${service} \u00B7 ${environment}`}
        </span>
        <div className="art:col-start-2 art:row-start-1 art:flex art:items-center art:justify-self-end art:gap-2 art:@min-[640px]/artemis:col-start-3">
          {headerActions}
          <span aria-hidden="true" className={artemisCx("art:size-2 art:rounded-full", paused ? "art:bg-muted-foreground" : "art:bg-success")}/>
          <ArtemisButton variant={paused ? "tertiary" : "primary"} className={`art:h-9 art:w-9 art:px-0 art:text-xs art:@min-[640px]/artemis:w-auto art:@min-[640px]/artemis:min-w-24 art:@min-[640px]/artemis:px-4 ${FOCUS_RING}`} aria-label={paused ? "Resume logs" : "Pause logs"} aria-pressed={paused} onClick={() => onPausedChange(!paused)}>
            {paused ? <Play aria-hidden className="art:size-3.5"/> : <Pause aria-hidden className="art:size-3.5"/>}
            <span className="art:hidden art:@min-[640px]/artemis:inline">{paused ? "Resume" : "Pause"}</span>
          </ArtemisButton>
        </div>
      </header>
      <div className="art:mx-3 art:flex art:min-h-0 art:flex-1 art:flex-col art:overflow-hidden art:rounded-2xl art:border art:border-border art:bg-background art:@min-[640px]/artemis:mx-4">
        <div className="art:flex art:shrink-0 art:flex-wrap art:items-center art:justify-between art:gap-2 art:px-3 art:py-2 art:@min-[640px]/artemis:px-5">
          <div className="art:max-w-full art:overflow-x-auto">
            <LevelTabs items={tabs} value={level} onValueChange={changeLevel} controls={`${id}-results`} ariaLabel="Filter log severity"/>
          </div>
          <div className="art:flex art:flex-col art:gap-1.5 art:min-w-0 art:flex-1 art:w-full art:@min-[640px]/artemis:w-60">
            <div data-state={searchFocused ? "focused" : "idle"} className={artemisCx("art:relative art:h-10 art:overflow-hidden art:rounded-full art:border art:bg-background art:transition-colors art:duration-200", searchFocused ? "art:border-foreground/60" : "art:border-border")}>
              <span className="art:pointer-events-none art:absolute art:left-3 art:top-1/2 art:flex art:-translate-y-1/2 art:items-center art:text-muted-foreground art:[&_svg]:h-4 art:[&_svg]:w-4">
                <Search aria-hidden className="art:size-4"/>
              </span>
              <input ref={searchRef} id={searchId} type="search" aria-label="Search logs" placeholder="Search logs…" className={artemisCx("art:peer art:h-full art:w-full art:bg-transparent art:text-foreground art:caret-foreground art:outline-none art:pl-10", query ? "art:pr-10" : "art:pr-3.5", "art:text-xs art:placeholder:text-muted-foreground")} value={query} onChange={(event) => changeQuery(event.target.value)} onFocus={() => setSearchFocused(true)} onBlur={() => setSearchFocused(false)}/>
              {query ? (<span className="art:absolute art:right-0 art:top-0 art:flex art:h-full art:items-center art:text-muted-foreground art:[&_button]:grid art:[&_button]:size-10 art:[&_button]:place-items-center art:[&_svg]:h-4 art:[&_svg]:w-4">
                  <ArtemisMorphicTooltip content="Clear search">
                    <ArtemisButton variant="ghost" size="icon" className={`art:size-9 ${FOCUS_RING}`} aria-label="Clear search" onClick={() => {
                changeQuery("");
                searchRef.current?.focus({ preventScroll: true });
            }}>
                      <X aria-hidden className="art:size-3.5"/>
                    </ArtemisButton>
                  </ArtemisMorphicTooltip>
                </span>) : null}
            </div>
            <div className="art:contents"/>
          </div>
        </div>
        <motion.div ref={listRef} layoutScroll role="tabpanel" id={`${id}-results`} aria-labelledby={`${id}-${level}`} tabIndex={0} onScroll={onScroll} className={artemisCx("art:min-h-0 art:flex-1 art:overflow-auto art:overscroll-contain art:px-2 art:py-3 art:@min-[640px]/artemis:px-4", scrolled && "art:[mask-image:linear-gradient(to_bottom,transparent,black_24px)]", FOCUS_RING)}>
          {visible.length === 0 ? (<div className="art:flex art:h-full art:flex-col art:items-center art:justify-center art:gap-3 art:px-4 art:py-8 art:text-center">
              <span className="art:flex art:size-12 art:items-center art:justify-center art:rounded-full art:border art:border-border art:text-muted-foreground">
                <CircleAlert aria-hidden className="art:size-5"/>
              </span>
              <p className="art:text-sm art:font-medium">No matching entries</p>
              <ArtemisButton variant="tertiary" className={`art:h-9 art:px-4 art:text-xs ${FOCUS_RING}`} onClick={clearFilters}>
                Clear filters
              </ArtemisButton>
            </div>) : (<motion.ul key={level} aria-label="Log entries" initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.14, ease: ARTEMIS_EASE_OUT }}>
              {visible.map((entry) => (<LogRow key={entry.id} entry={entry} expanded={expandedId === entry.id} onToggle={() => {
                    setExpandedId((current) => (current === entry.id ? null : entry.id));
                    setFollowing(false);
                }}/>))}
            </motion.ul>)}
        </motion.div>
      </div>
      <footer className="art:flex art:shrink-0 art:flex-wrap art:items-center art:justify-between art:gap-3 art:px-4 art:py-2 art:font-mono art:text-xs art:text-muted-foreground art:@min-[640px]/artemis:px-6">
        <span className="art:flex art:flex-wrap art:items-center art:gap-x-2 art:gap-y-1">
          <Circle aria-hidden className="art:size-2 art:fill-current"/>
          <span>{paused ? "Paused" : "Live"}</span>
          <span aria-hidden="true">·</span>
          <span className="art:tabular-nums">
            {visible.length} of {shown.length} entries
          </span>
          {pending > 0 ? <span className="art:text-foreground">{`+${pending} new`}</span> : null}
        </span>
        {following ? (<span>Following latest</span>) : (<ArtemisButton variant="ghost" className={`art:h-9 art:px-3 art:text-xs ${FOCUS_RING}`} onClick={jumpToLatest}>
            <ArrowDown aria-hidden className="art:size-3.5"/> Jump to latest
          </ArtemisButton>)}
      </footer>
      <output className="art:sr-only" aria-live="polite">
        {`Log display ${paused ? "paused" : "live"}.`} {pending > 0 ? `${pending} new entries available.` : ""}
      </output>
    </section>);
}

"use client";
// @zeus-internal
import { Check, ChevronRight, Copy } from "lucide-react";
import { motion, type Transition } from "motion/react";
import { useEffect, useId, useRef, useState } from "react";
import { ArtemisButton } from "../../../../foundations/button";
import { artemisButtonClasses } from "../../../../foundations/button-classes";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_LAYOUT, ARTEMIS_SPRING_PRESS } from "../../../../lib/ease";
