});
type CopyState = "idle" | "copied" | "failed";
function Payload({ entry, id, copy, onCopy }: {
    entry: LogEntry;
    id: string;
    copy: CopyState;
    onCopy: () => void;
}) {
    const json = JSON.stringify(entry.payload, null, 2);
    return (<motion.section layout="position" id={id} aria-label={`Details for ${entry.message}`} className="art:px-3 art:pb-3 art:@min-[640px]/artemis:px-4 art:@min-[640px]/artemis:pb-4" initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={PAYLOAD_TRANSITION}>
      <div className="art:flex art:items-center art:justify-between art:gap-3 art:border-t art:border-border art:pt-2 art:pb-1">
        <span className="art:text-xs art:text-muted-foreground">Payload</span>
